(function () {
  const groupLabels = {
    "控制": "Control", "资产": "Assets", "界面": "Interface", "局部校对": "Bounded proofreading",
    "参考": "References", "上下文": "Context", "清单": "Manifest", "复用": "Reuse", "模型": "Models",
    "子 Agent": "Subagents", "读取": "Read", "对齐": "Alignment", "校对": "Proofreading", "写入": "Write",
    "检索": "Search", "最终检查": "Final checks", "翻译写入": "Translation writes", "验证": "Validation",
    "校对写入": "Proofread writes", "校对资产": "Proofread assets", "校对完成": "Proofread completion",
    "校对控制": "Proofread control", "校对调度": "Proofread scheduling", "通用委派": "General delegation",
    "翻译调度": "Translation scheduling", "通用只读": "General read-only", "翻译": "Translation",
    "翻译修复": "Translation repair", "翻译验证": "Translation validation", "校对参考": "Proofread references",
    "局部委派": "Bounded delegation", "独立审阅": "Independent review", "复用审计": "Reuse audit"
  };

  const functionSummaries = {
    resumeYnWorkflow: "Idempotently resume a parked full translation or proofreading workflow; succeed as a no-op when already active or absent.",
    readTranslationDiscoveries: "Page through Host-persisted terminology and character discoveries without rereading Child transcripts.",
    resolveTranslationDiscoveries: "Accept or reject discoveries, then update glossary candidates or merge validated character facts.",
    readYnInterfaceContext: "Read the currently visible page, line range, and focused row for requests such as 'this line' or 'this page'.",
    inspectProofreadRange: "Open a hash-bound local review scope for an exact aligned range.",
    fetchWebReference: "Fetch, extract, and cache an explicit HTTP(S) reference so Parent and Children can reuse it safely.",
    inspectTranslationContext: "Return bound source, candidate, assets, translation memory, and prescan state in one inspection.",
    selectSourceDocument: "Transactionally select one document inside the immutable Host manifest without expanding workflow scope.",
    prepareTranslationReuseAudit: "Run a hash-bound mechanical screen over the retained manifest and send only risky rows to semantic audit.",
    readTranslationReuseAudit: "Read a bounded page of risky source/translation pairs with adjacent context.",
    recordTranslationReuseAudit: "Record a binary reuse or retranslate decision for each risky row.",
    runTranslationReuseAudit: "Start persistent, read-only Pi audit Workers; ordinary low-risk rows never enter the model.",
    applyTranslationReuseDecision: "Apply one batch-level user decision transactionally: back up, retain accepted rows, and clear retranslation rows.",
    listAvailableModels: "Page through configured models only when the user explicitly requests a Child model override.",
    inspectSubagents: "Read lightweight Child status and assignment progress; normal completion wakes the Parent automatically.",
    steerSubagent: "Send a short Steer message to a named Pi Child that is still running.",
    readSourceLines: "Read up to 512 one-based lines from the bound source.",
    readTranslationLines: "Read up to 512 one-based lines from the current translation candidate.",
    readTranslationAlignmentRows: "Read Host-selected rows and up to two neighboring source/translation rows during an active Parent alignment audit.",
    recordProofreadParentReview: "Record that the Parent actually completed semantic review of an aligned range.",
    readProjectFile: "Read a bounded UTF-8 page, including an explicit absolute reference outside the project.",
    writeProjectFile: "Write only approved workspace assets or settings; candidates and findings use dedicated Functions.",
    listProjectDir: "List a project or explicit external reference directory without writing.",
    searchProjectText: "Return bounded match-centered evidence; indexed assets return complete structured records.",
    searchTranslationMemory: "Run a bounded search over previously accepted aligned segments in this project.",
    inspectTranslationWarnings: "Open unaccepted non-blocking warnings with canonical paired rows and bounded context.",
    recordTranslationWarningChecks: "Submit only confirmed warning failures; an empty list accepts the page as hash-current false positives.",
    inspectTranslationAlignment: "Open a hash-bound alignment audit for Parent-owned exact or local repairs.",
    recordTranslationAlignmentChecks: "Submit only rows that still fail; an empty list accepts all Host-selected rows.",
    writeTranslationChunk: "Validate and atomically write an exact line range for the specified document.",
    validateTranslationArtifact: "Run final validation for the bound file, full folder workflow, or locally modified document.",
    writeProofreadFindings: "Validate and merge normalized findings, replacing old findings only inside the active local scope.",
    resolveProofreadGlossaryCandidates: "Accept or reject evidence-backed proper-name candidates reported by proofread Workers.",
    finalizeProofreadReport: "Validate the single findings JSON and close the proofreading completion gate.",
    resolveProofreadMontecarloLimit: "Resolve a non-converged round limit by continuing three rounds, switching to HOT split, or stopping with current results.",
    runProofreadSubagents: "Start Host-planned persistent proofread Workers; splitSize shapes tasks while workerCount limits concurrency.",
    runSubagents: "Delegate explicit investigation or exact translation repair without replacing it with a full workflow.",
    runTranslationSubagents: "Start the Host-owned translation queue; the Host determines manifest order, chunks, reuse masks, and settlement.",
    readTranslationContext: "Read one bounded source/translation context window without expanding write authority.",
    readAssignedSource: "Read the assigned source chunk, built-in rules, and directly matched project references.",
    writeAssignedTranslation: "Merge line-identified translations into Host staging while preserving all other valid rows.",
    repairAssignedTranslation: "Repair only the exact lines named by the Host and preserve previously accepted rows.",
    validateAssignedTranslation: "Validate the owned range and report terminology or character discoveries once, then end the artifact turn.",
    readAssignedProofreadContext: "Read all owned rows, boundary context, deterministic signals, built-in rules, and approved references.",
    readProofreadReference: "Page only through an extra proofread reference marked complete=false in the assignment manifest.",
    writeAssignedFindings: "Submit strictly scoped findings and proper-name candidates; no-op fixes are rejected.",
    readBoundSourceLines: "Read exact source lines from the document delegated by the Parent.",
    readBoundTranslationLines: "Read exact candidate lines from the document delegated by the Parent.",
    readAssignedTranslationReview: "Read all mechanical-risk rows, deterministic clean samples, and short neighboring context.",
    submitTranslationReview: "Submit only concrete failed rows with short actionable notes; passing rows stay silent.",
    readAssignedTranslationAudit: "Read the exact source/current-translation pairs assigned for reuse audit.",
    submitTranslationAudit: "Submit reuse or retranslate for every row requiring semantic audit."
  };

  function functionCards(data, runtime, helpers) {
    const items = runtime === "parent" ? data.parentFunctions : data.childFunctions;
    return items.map((item, index) => {
      const summary = functionSummaries[item.name] || item.name;
      const detail = data.functionDetails[`${runtime}:${item.name}`] || {};
      const group = groupLabels[item.group] || item.group;
      const params = item.params.length ? item.params.map((param) => `<span class="chip">${helpers.esc(param)}</span>`).join("") : '<span class="chip">No model arguments</span>';
      const searchable = [item.name, group, summary, ...item.params].join(" ").toLowerCase();
      return `<details class="function-item" id="${runtime}-${helpers.slug(item.name)}" data-function data-runtime="${runtime}" data-group="${helpers.esc(item.group)}" data-search="${helpers.esc(searchable)}"><summary><span class="function-name">${item.name}</span><span class="function-group">${runtime === "parent" ? "Parent Host" : "Child runtime"} · ${group}</span><span class="function-summary">${summary}</span><span class="function-caret">›</span></summary><div class="function-body">
        <div class="function-contract"><div><span>Boundary</span><p>${runtime === "parent" ? "Parent Agent calling a Host-owned domain surface." : "A Host-bounded Child assignment runtime."}</p></div><div><span>Purpose</span><p>${summary}</p></div><div><span>Input</span><p>${item.params.length ? item.params.join(", ") : "No model-authored arguments."}</p></div><div><span>State authority</span><p>The Host validates identity, scope, hashes, and schema before any state change.</p></div><div class="danger-cell"><span>Rejected when</span><p>The active session, document, ownership, input hash, or schema does not match the operation contract.</p></div><div><span>Result</span><p>A structured tool result returned to the same Pi turn.</p></div></div>
        <div class="function-foot"><div><strong>Parameter index</strong><div class="chip-row">${params}</div></div><code>${helpers.esc(String(detail.source || "source reference" ).replace(/:\d+$/, ""))}</code><span>${index + 1} / ${items.length}</span></div>
      </div></details>`;
    }).join("");
  }

  window.YN_GUIDE_EN = {
    pageMeta: {
      overview: { file: "index.html", num: "⌂", label: "Reading guide", section: "home" },
      guides: { file: "guides.html", num: "1", label: "Start here", section: "tutorial" },
      features: { file: "features.html", num: "2", label: "Settings guide", section: "tutorial" },
      workflows: { file: "workflows.html", num: "A", label: "Two workflows", section: "technical" },
      harness: { file: "harness.html", num: "B", label: "Harness architecture", section: "technical" },
      functions: { file: "functions.html", num: "C", label: "Function reference", section: "technical" },
      terminology: { file: "terminology.html", num: "0", label: "Agent terminology", section: "technical", navOrder: 1 }
    },
    ui: {
      navEntry: "Entry", navTutorial: "User tutorial", navTechnical: "Technical manual", navDirect: "Quick links",
      directTranslation: "Run a full translation", directRemote: "Phone and remote use", directGlossary: "Using glossaries", directTerms: "Terminology update path",
      search: "Search tutorials or technical entries", searchPlaceholder: "Try: remote, reuse, staging, Host, or a Function name",
      searchEmpty: "No matching entry. Try “Host”, “staging”, “reuse”, or a Function name.",
      handbook: "Tutorial and technical manual", callable: "callable surfaces", edit: "Edit text", editing: "Editing",
      verified: "Checked against current source", toc: "On this page", close: "Close", enlarge: "Enlarge",
      productScreenshot: "Product interface",
      done: "Done", export: "Export all", import: "Import copy", reset: "Reset this language", saved: "Saved automatically",
      exported: "Copy from every page has been collected", formatError: "The copy file format is invalid.", importConfirm: "Importing will replace saved copy for both languages in this browser. Continue?",
      resetConfirm: "Reset edits on this page for the current language to your saved baseline?", editorStatus: "Edit mode",
      functionCount: "runtime surfaces shown"
    },
    groups: groupLabels,
    functionSummaries,
    renderers: {
      overview(h) {
        return `${h.pageHead("Choose the path that matches your goal", "YN Translation Workshop", "This guide is split into two books. Use the tutorial for first-time setup and remote operation; use the technical manual to understand Agents, Host, Workers, terminology gates, and Functions.")}
          <section class="route-grid" aria-label="Reading paths"><a class="route-panel route-tutorial" href="guides.html"><span class="route-label">User tutorial</span><h2>I want to get a translation running</h2><p>Follow the names shown in the interface: what to select, what to enter, and when to press each command.</p><span class="route-action">Start from zero <b>→</b></span></a><a class="route-panel route-technical" href="terminology.html"><span class="route-label">Technical manual</span><h2>I want to understand why it is reliable</h2><p>Begin with the vocabulary, then trace the two real workflows through runtime, scheduling, permissions, evidence, and recovery.</p><span class="route-action">Open the architecture <b>→</b></span></a></section>
          <h2 id="plain-overview">The one-sentence explanation</h2><p class="lead">It is a local translation and proofreading workbench. It turns TXT or EPUB content into an aligned page for reading and editing, then lets an Agent translate or inspect the text inside an enforceable workflow.</p>
          <div class="plain-strip"><div><strong>Source stays read-only</strong><span>The workflow does not directly rewrite the real source file.</span></div><div><strong>HTML is the workspace</strong><span>Line editing, issue review, approvals, and remote sync happen in the page.</span></div><div><strong>TXT is written last</strong><span>Confirmed results are written back only after review.</span></div></div>
          <h2 id="what-you-can-do">What it can do</h2><div class="three-col"><article class="topic-card"><span class="num">Translate</span><h3>Create a candidate from scratch</h3><p>Process one file, a folder, or EPUB input with bounded parallel chunks and independent review.</p></article><article class="topic-card"><span class="num">Proofread</span><h3>Inspect an existing translation</h3><p>Turn real issues into suggestions that can be accepted, rejected, or edited.</p></article><article class="topic-card"><span class="num">Assist</span><h3>Ask the Agent at any time</h3><p>Send a selected line with context, inspect tools, and open Child work when needed.</p></article><article class="topic-card"><span class="num">Assets</span><h3>Maintain terminology and characters</h3><p>Approved terms, candidates, character facts, and style rules remain project-scoped.</p></article><article class="topic-card"><span class="num">Remote</span><h3>Continue on a phone</h3><p>Use the LAN page while the desktop application remains running.</p></article><article class="topic-card"><span class="num">Safety</span><h3>Keep changes inspectable</h3><p>Candidate output, HTML state, and the real TXT remain separate until write-back.</p></article></div>
          <h2 id="two-workflows">Only two complete workflows</h2><div class="choice-strip"><div><span>01</span><strong>Initial translation</strong><p>Read source and project references, produce aligned candidate output, review each chunk, and validate the whole artifact.</p></div><div><span>02</span><strong>Proofreading</strong><p>Read source and current translation, identify actionable problems, and produce review findings.</p></div></div><p>Terminology, character voice, reuse, and final QA are stages inside these workflows, not extra workflows.</p>
          <h2 id="recommended-reading">Recommended order</h2><ol class="step-list"><li><strong><a href="guides.html">Complete one small run with the tutorial</a></strong><br>Generate HTML, translate, sync, proofread, approve, and write TXT.</li><li><strong><a href="features.html">Adjust project settings only after that</a></strong><br>Pay special attention to split size, Agent limits, reuse, and glossary candidates.</li><li><strong><a href="terminology.html">Learn the technical vocabulary</a></strong><br>Then follow the two workflows into Harness architecture and the Function Registry.</li></ol>`;
      },
      features(h) {
        return `${h.pageHead("User tutorial 02", "How to fill in the settings", "Each screenshot stays beside the setting it explains, so you can follow the interface directly.")}
          <div class="tutorial-banner"><strong>First-run rule</strong><span>Change only language direction, content type, work description, and output location. Keep the rest at defaults until a small test succeeds.</span></div>
          <h2 id="project-inputs">Main workbench fields</h2>${h.image("workbench.png", "Full YN Translation Workshop workbench", "Workbench overview. The paths, input mode, and proxy settings below refer to this screen.")}
          <div class="table-wrap"><table class="field-guide"><thead><tr><th>Interface label</th><th>What to enter</th><th>Practical advice</th></tr></thead><tbody><tr><td><strong>Route Agent traffic through proxy</strong></td><td>Enable only when the selected model service actually requires your local proxy.</td><td>Off by default. Use the address and port shown by your own proxy application.</td></tr><tr><td><strong>Source file or folder</strong></td><td>Select the TXT, EPUB, or folder containing the source text.</td><td>Game scripts usually use folders; one novel volume can use TXT or EPUB.</td></tr><tr><td><strong>Translation file or folder</strong></td><td>Select existing translation input, or leave blank for a clean initial translation.</td><td>Proofreading requires aligned translation input.</td></tr><tr><td><strong>Output folder</strong></td><td>Select the project workspace for HTML, candidates, reports, and assets.</td><td>Use a separate folder for every title.</td></tr><tr><td><strong>Glossary file path</strong></td><td>Select an external approved glossary when you already have one.</td><td>Selection binds the external authority. Importing accepted candidates later consolidates it with canonical and switches only after a conflict-free merge.</td></tr><tr><td><strong>Input mode</strong></td><td>Choose separate files or an interleaved bilingual file.</td><td>For bilingual input, confirm which position contains source and translation.</td></tr><tr><td><strong>Rows per page</strong></td><td>Controls only HTML pagination.</td><td>It does not change Agent assignment size.</td></tr></tbody></table></div>
          <h2 id="model-settings">AI service and model</h2><p>Configure the service in Agent settings. Codex subscriptions can use OAuth; compatible services can use an API endpoint and key. Test a normal conversation before starting a workflow.</p><div class="reference-pair">${h.image("provider-config.png", "Compatible API configuration", "A custom API needs an endpoint, model ID, default model, and credential.")}${h.image("model-config.png", "ChatGPT OAuth and default model", "For a Codex subscription, sign in with OAuth and select the default model.")}</div><p>A successful ordinary Agent message confirms the connection. The next screen shows a completed proofreading response.</p>${h.image("agent-proofread.png", "Agent completed proofreading", "Tool calls and the final response appear in one conversation stream.")}<p>Use “New window” to observe the Agent beside the HTML workspace.</p>${h.image("agent-conversation.png", "Separate Agent window", "The separate window keeps sessions, tool calls, composer, and model state visible.")}<div class="note warning"><strong>A proxy is not automatically better</strong>Enable it only when the model service or a requested web reference needs it.</div>
          <h2 id="prompt-basics">Translation parameters</h2>${h.image("prompt-settings.png", "Translation parameters and file order", "Language pair, style, split size, work description, file order, and preserve rules are configured here.")}<div class="table-wrap"><table class="field-guide"><thead><tr><th>Interface label</th><th>Meaning</th><th>Example or advice</th></tr></thead><tbody><tr><td><strong>Language pair</strong></td><td>Source language first, target language second.</td><td><code>ja-&gt;zh-CN</code> means Japanese to Simplified Chinese.</td></tr><tr><td><strong>Style</strong></td><td>Select the closest content type and refine tone in the description.</td><td>Game, light novel, visual novel; natural dialogue with honorific distinctions.</td></tr><tr><td><strong>Split size</strong></td><td>Maximum rows in one Host assignment.</td><td>Reduce it for context-sensitive dialogue; begin with the default.</td></tr><tr><td><strong>Work description</strong></td><td>Describe setting, era, principal characters, naming rules, and reliable URLs.</td><td>Official wikis or character pages can help the Agent research ambiguity.</td></tr><tr><td><strong>File translation order</strong></td><td>Items outside braces are sequential; items inside one brace group share a parallel stage.</td><td>Remove files you do not want in this run.</td></tr><tr><td><strong>Regex preserve rules</strong></td><td>Define project-specific variables, event codes, name boxes, or control sequences.</td><td>Matched payload must remain byte-for-byte on the same translated row.</td></tr></tbody></table></div>
          <h2 id="translation-settings">Child Agents, candidates, and reuse</h2>${h.image("project-assets.png", "Child Agent and workflow settings", "Concurrency, models, glossary candidates, character bible, reuse, and proofreading controls.")}<div class="setting-list"><article><h3>Child Agent count</h3><p>A 1..N concurrency ceiling, not an exact number. New projects default to 3.</p></article><article><h3>Review Agent count</h3><p>A separate read-only pool checks initial translation. It follows the translation limit by default.</p></article><article><h3>Child model</h3><p>Children inherit the Parent model unless you explicitly select a configured alternative.</p></article><article><h3>Glossary candidates</h3><p>Collect new proper names. Conflicting targets pause new claims until the Parent decides and affected rows are repaired.</p></article><article><h3>Character bible</h3><p>Collect evidence about names, gender, pronouns, address, and voice. Unknown remains valid when evidence is insufficient.</p></article><article><h3>Audit and reuse existing translation</h3><p>Use only when part of the existing translation is reliable. The Host screens it, semantic Workers decide risky rows, and you make one batch decision.</p></article></div>
          <h2 id="proofread-settings">Proofreading parameters</h2><div class="two-col"><article class="topic-card"><span class="num">Full</span><h3>Split proofreading</h3><p>Every row receives semantic review; split size controls persistence and assignment boundaries.</p></article><article class="topic-card"><span class="num">Sample</span><h3>Monte Carlo</h3><p>Review HOT regions first, then non-repeating stratified samples. Continued discoveries never masquerade as convergence.</p></article></div><div class="table-wrap"><table class="field-guide"><thead><tr><th>Interface label</th><th>Meaning</th><th>When to change</th></tr></thead><tbody><tr><td><strong>H9 candidate ratio</strong></td><td>A mechanical warning for unusually long target text.</td><td>It is evidence, not an automatic error; adjust for language-pair length differences.</td></tr><tr><td><strong>Monte Carlo sample size</strong></td><td>Maximum rows sampled per round.</td><td>Increase for broader coverage of a large project.</td></tr><tr><td><strong>Minimum / maximum rounds</strong></td><td>Minimum evidence collection and the point at which the user must choose.</td><td>The maximum is not automatic approval.</td></tr></tbody></table></div>
          <h2 id="project-assets">Project-level assets</h2>${h.image("preserve-rules.png", "Project assets and regex preserve rules", "Maintain approved terminology, character records, style guidance, and project preserve rules here.")}<p>Terminology, character facts, and style are long-lived project assets. Invalid regular expressions fail explicitly.</p>${h.image("html-theme.png", "HTML theme colors", "Theme selection changes only the review page appearance.")}<p>Theme colors do not modify translation or issue state.</p>`;
      },
      guides(h) {
        return `${h.pageHead("User tutorial 01", "Start from zero", "The instructions follow the actual operating order, with each screenshot beside its matching step.")}
          <h2 id="quickstart">The fastest complete path</h2><ol class="step-list"><li><strong>Select source and output folder</strong><br>Translation can start without a target file; proofreading requires aligned target input.</li><li><strong>Generate line-by-line HTML</strong><br>Check the manifest and row counts first. Source remains unchanged.</li><li><strong>Configure the AI service</strong><br>Use OAuth or a compatible API and test one ordinary message.</li><li><strong>Select Initial translation and generate the prompt</strong><br>Keep defaults for the first small run.</li><li><strong>Refresh the candidate translation</strong><br>Inspect names, placeholders, blanks, and language direction.</li><li><strong>Run Proofreading and generate review HTML</strong><br>Accept, reject, or edit each suggestion.</li><li><strong>Write TXT</strong><br>Only after page state is confirmed.</li></ol><div class="tutorial-banner"><strong>Begin with 50 to 200 rows</strong><span>Validate encoding, alignment, terminology, and control codes before processing the entire project.</span></div>
          <h2 id="html">Understand the two HTML views</h2><h3>Folder and single-file pages</h3>${h.image("folder-review.png", "Folder line-review HTML", "The folder page selects files, shows overall state, opens child pages, and performs batch write-back.")}${h.image("line-review.png", "Single-file line-review HTML", "The single-file page is the main reading, editing, searching, and issue-review workspace.")}<p>The folder page is the index and control surface; the single-file page is where most reading and editing happens.</p>
          <h2 id="translation">Run a full translation</h2><ol class="step-list"><li><strong>Select Initial translation under Full workflow</strong><br>There are only two choices; terminology and character handling are internal stages.</li><li><strong>Enter language, content type, and work description</strong><br>Add reliable official references when available.</li><li><strong>Choose whether to reuse old translation</strong><br>Leave it off unless part of the old candidate is genuinely reliable.</li><li><strong>Generate and send the translation prompt</strong><br>The page saves project settings first and stops on save failure.</li><li><strong>Wait for completion</strong><br>The Parent plans and consolidates; Children process Host-bounded assignments.</li></ol><p>The minimal path is source, project folder, HTML, model configuration, translation prompt, and send. When it completes, refresh candidate output in the HTML.</p>${h.image("refresh-translation.png", "Refresh Agent translation output", "After the Agent completes, refresh to scan candidate translation files again.")}<p>Review a sample before proofreading. Candidate HTML state is not written to real TXT automatically.</p>
          <h2 id="reuse">Handling existing translation</h2><div class="choice-strip"><div><span>Off</span><strong>Clean retranslation</strong><p>The Host backs up the old candidate, clears translation debt once, and starts clean. Backups remain readable references.</p></div><div><span>On</span><strong>Audit then reuse</strong><p>Clearly safe rows remain, while risky rows receive semantic decisions. You then keep accepted rows or discard the old candidate.</p></div></div><p>Reuse suits partly human-translated or otherwise reliable work. Unstable machine translation is usually simpler to retranslate cleanly.</p>
          <h2 id="proofread">Proofread existing translation</h2><ol class="step-list"><li><strong>Confirm strict source/target alignment</strong><br>Repair row mismatches before starting.</li><li><strong>Select Proofreading and send the prompt</strong><br>Use split mode for final delivery and Monte Carlo for a quick quality survey.</li><li><strong>Wait, then generate review HTML</strong><br>Code scans deterministic risks first; Agents then judge semantics with context.</li></ol>${h.image("proofread-review.png", "Proofreading suggestion page", "Each suggestion includes source, current translation, and the proposed correction.")}<p>Actionable suggestions begin accepted, but you should still read them. One-click apply synchronizes HTML state; writing the real target still requires Write TXT or Batch write TXT.</p>
          <h2 id="assets">Glossary, candidates, and character bible</h2><p>The approved glossary has the highest terminology priority. Glossary candidates are provisional discoveries. Import consolidates the existing canonical glossary, the selected external glossary, and accepted candidates; conflicts reject the operation, and only a successful merge switches the project binding to canonical.</p>${h.image("glossary-editor.png", "Glossary management", "View approved and candidate entries, filter states, preview replacement, and import accepted candidates.")}<p>Translation already injects directly matched approved terms, candidate terms, and character records. No separate “read glossary workflow” is required.</p>
          <h2 id="line-editing">Human translation and row actions</h2><p>Manual edits are highlighted. Restore row returns to the imported candidate baseline, while issue colors indicate severity.</p>${h.image("issue-row.png", "Translation row with an H2 issue", "After correcting an H2 issue, explicitly clear the issue when satisfied.")}<ul class="plain-check"><li>Correct text does not silently clear a review issue; the user confirms it.</li><li>Select source text and use the context menu to ask the Agent with bounded context.</li><li>Preview glossary replacement before applying it across large files.</li></ul>
          <h2 id="agent">Read the Agent conversation</h2><p>You can ask for progress while the full workflow runs. Thinking, Functions, and subagents appear as structured expandable blocks.</p>${h.image("tool-call.png", "Expanded Function call", "Expand a Function card to inspect its input, duration, and result.")}${h.image("subagent-card.png", "Child Agent card", "A Child card shows its assignment and status and can open the Child conversation.")}<p>Opening the card lets you inspect the exact task and tool calls rather than trusting a one-line Parent summary.</p>${h.image("token-telemetry.png", "Agent tokens and estimated cost", "The conversation header displays input, output, cache tokens, and estimated cost.")}<p>Estimated cost may differ from provider billing.</p>${h.image("slash-commands.png", "Agent slash command menu", "Type a slash to see commands and choose Steer or Follow-up while work is running.")}<p>Steer is consumed soon after the active tool returns; Follow-up waits until current work completes.</p>
          <h2 id="lan">Phone, LAN, and public remote access</h2><p>Open the HTML in the desktop app, enter your own six-digit PIN, and start LAN sync. The desktop app must remain running.</p><div class="reference-pair wide-pair">${h.image("lan-settings.png", "LAN sync settings", "The desktop page shows the PIN, local and LAN addresses, and stop control.")}${h.image("lan-browser.png", "Synced page on a phone", "The remote page can edit translation and open the Agent panel.")}</div><p>For internet access, point a tool such as Cloudflare Tunnel or ngrok at the local sync address. Public tunneling is not built into the application.</p>${h.image("tunnel-terminal.png", "Cloudflare Tunnel console", "The tunnel command returns a temporary public address that stops with the process.")}<pre class="band"><code>cloudflared tunnel --url http://127.0.0.1:PORT_SHOWN_BY_THE_PAGE</code></pre><div class="note danger"><strong>A public URL exposes the workbench to the internet</strong>Use an unguessable PIN, do not publish the temporary URL, and stop both the tunnel and LAN sync when finished.</div><p>The public remote page also exposes the Agent panel for progress checks and queued messages.</p>${h.image("agent-panel.png", "Agent panel in the remote page", "The remote Agent panel shows progress, accepts messages, and lets you continue working.")}
          <h2 id="troubleshooting">Quick troubleshooting</h2><div class="table-wrap"><table><thead><tr><th>Symptom</th><th>Check first</th><th>Action</th></tr></thead><tbody><tr><td>No Agent response</td><td>Service, credential, model, and proxy compatibility</td><td>Test a plain message in a new session.</td></tr><tr><td>Generated prompt still uses old settings</td><td>Whether project save succeeded</td><td>Fix the path or permission error, then regenerate.</td></tr><tr><td>Proofreading cannot start</td><td>Row counts and file matching</td><td>Repair strict alignment instead of hiding it with blank rows.</td></tr><tr><td>Terminology flow is paused</td><td>Multiple targets for one source term</td><td>Review evidence and choose one target; affected rows are repaired first.</td></tr><tr><td>Phone cannot connect</td><td>Desktop app, same network, firewall</td><td>Restart sync and use the displayed LAN address.</td></tr><tr><td>Continue after Stop</td><td>Whether recovery state remains in the same session</td><td>Explicitly continue in that session so valid staging and evidence can be reused.</td></tr></tbody></table></div>`;
      },
      workflows(h) {
        const flow = (items, compact = false) => `<div class="architecture-flow${compact ? " compact" : ""}">${items.map((item, index) => `<div><span>${String(index + 1).padStart(2, "0")}</span><strong>${item}</strong></div>`).join("")}</div>`;
        return `${h.pageHead("Technical manual A", "The complete path of both workflows", "The Registry exposes only Initial translation and Proofreading as complete entry points. This page follows data through UI, Pi runtime, Host, Workers, validators, and artifacts.")}<div class="technical-intro"><span>Before reading</span><p>A Workflow is the whole executable contract from entry point to completion gate. Reuse audit, terminology gates, local repair, and Monte Carlo are bounded subflows.</p></div>
          <h2 id="registry">Workflow Registry</h2><div class="choice-strip"><div><span><code>initial_translation</code></span><strong>Initial translation</strong><p>Produces aligned candidate translation through chunk writes, independent review, terminology coordination, and final validation.</p></div><div><span><code>proofread</code></span><strong>Proofreading</strong><p>Produces one findings JSON that the product renders as human review HTML.</p></div></div>
          <h2 id="translation-workflow">Initial translation: Prompt to candidate</h2>${flow(["Save project settings", "Build manifest", "Handle old translation", "Plan translation debt", "Write staging", "Independent review", "Coordinate terminology", "Validate whole artifact"])}<div class="workflow-timeline"><section class="workflow-step"><div class="workflow-step-index">01</div><div class="workflow-step-main"><h3>UI persists this run's settings</h3><p>File bindings, language, split size, file order, reuse, and concurrency limits are written before the marked Prompt is generated.</p></div></section><section class="workflow-step"><div class="workflow-step-index">02</div><div class="workflow-step-main"><h3>Host builds the authoritative manifest</h3><p>Single files, ordered folders, and extracted EPUB text become documents with identity, paths, row counts, and stages.</p></div></section><section class="workflow-step"><div class="workflow-step-index">03</div><div class="workflow-step-main"><h3>Old translation branches</h3><p>Reuse off backs up and clears once; reuse on mechanically screens all rows and sends only risks to read-only semantic audit.</p></div></section><section class="workflow-step"><div class="workflow-step-index">04</div><div class="workflow-step-main"><h3>Host creates the real debt queue</h3><p>Assignments are non-overlapping and derived from split size, file stages, reuse masks, and current accepted evidence.</p></div></section><section class="workflow-step"><div class="workflow-step-index">05</div><div class="workflow-step-main"><h3>Translation Worker reads and writes</h3><p>It receives owned source, short context, and directly matched assets, then writes Host-managed staging.</p></div></section><section class="workflow-step"><div class="workflow-step-index">06</div><div class="workflow-step-main"><h3>Review Worker judges independently</h3><p>The Host supplies every mechanical risk plus stable clean samples. Only failures return to the original translation Worker.</p></div></section><section class="workflow-step"><div class="workflow-step-index">07</div><div class="workflow-step-main"><h3>Terminology becomes a priority repair wave</h3><p>Matching discoveries merge evidence; competing targets close new assignment claims until the Parent decides and affected rows pass review.</p></div></section><section class="workflow-step"><div class="workflow-step-index">08</div><div class="workflow-step-main"><h3>Whole-artifact validation and warning postcheck</h3><p>Blocking debt must reach zero. Unreviewed warnings become paired semantic checks, then false-positive evidence or exact repair debt.</p></div></section></div>
          <h3 id="translation-input-map">Where inputs are first used</h3><div class="table-wrap"><table><thead><tr><th>Input</th><th>First use</th><th>Later effect</th></tr></thead><tbody><tr><td>Language, content type, work description</td><td>Prompt and Parent context</td><td>Assignment framing, target-language checks, explicit web references</td></tr><tr><td>Split size and file order</td><td>Host planning</td><td>Dynamic claims, stage barriers, cold recovery debt</td></tr><tr><td>Approved glossary, candidates, character bible</td><td>Context inspection</td><td>Only complete records directly matched by each assignment source are injected</td></tr><tr><td>Regex preserve rules</td><td>Project normalization</td><td>Reuse screen, chunk validation, final validation</td></tr><tr><td>Existing candidate translation</td><td>Reuse preparation or first write</td><td>Retained baseline and optional read-only backup reference</td></tr></tbody></table></div>
          <h2 id="proofread-workflow">Proofreading: aligned text to Findings</h2>${flow(["Bind source and target", "Prescan all documents", "Plan coverage", "Semantic review", "Merge Findings", "Human approval"], true)}<ol class="technical-steps"><li><span>01</span><div><strong>Bind</strong><p>Each document owns its source and candidate path; identity or row mismatch fails before Workers start.</p></div></li><li><span>02</span><div><strong>Deterministic prescan</strong><p>The Host scans formatting, protected payloads, terminology, and length signals and binds them to all input hashes.</p></div></li><li><span>03</span><div><strong>Plan</strong><p>Split covers every row; Monte Carlo uses non-repeating HOT, WARM, and COLD strata with explicit convergence.</p></div></li><li><span>04</span><div><strong>Semantic Workers</strong><p>Workers confirm or reject deterministic signals and find semantic issues that code cannot detect.</p></div></li><li><span>05</span><div><strong>One report</strong><p>Scope replacement merges Findings into one JSON without duplicate rerun output.</p></div></li><li><span>06</span><div><strong>Visual approval</strong><p>HTML presents the JSON; the user decides what to apply and when to write real TXT.</p></div></li></ol>
          <h2 id="completion">How completion is decided</h2><div class="formula"><code>complete</code><b>=</b><code>manifest covered</code><b>∧</b><code>tasks accepted</code><b>∧</b><code>review debt zero</code><b>∧</b><code>shared assets settled</code><b>∧</b><code>final validation passed</code></div><p>Completion comes from Host-persisted identities, hashes, ranges, and verdicts. A premature model completion claim becomes another repair turn.</p>
          <h2 id="bounded-flows">Bounded subflows inside the workflows</h2><div class="table-wrap"><table><thead><tr><th>Subflow</th><th>Trigger</th><th>Returns to</th></tr></thead><tbody><tr><td>Reuse audit</td><td>Translation starts with reuse enabled</td><td>Retained baseline and sparse retranslation debt</td></tr><tr><td>Terminology conflict</td><td>One source term receives competing targets</td><td>Priority repair wave in the active translation batch</td></tr><tr><td>Chunk review</td><td>Mechanical validation passes</td><td>Promotion or exact repair by the original Worker</td></tr><tr><td>Final warning postcheck</td><td>Blocking findings are zero</td><td>Exact Parent repair or accepted false-positive evidence</td></tr><tr><td>Monte Carlo limit decision</td><td>New issues remain at the maximum round</td><td>User chooses three more rounds, HOT-only split, or current result</td></tr><tr><td>Local repair or investigation</td><td>User names a file or exact rows</td><td>Bounded operation without creating a full workflow</td></tr></tbody></table></div>`;
      },
      harness(h) {
        const flow = (items) => `<div class="architecture-flow compact">${items.map((item, index) => `<div><span>${String(index + 1).padStart(2, "0")}</span><strong>${item}</strong></div>`).join("")}</div>`;
        return `${h.pageHead("Technical manual B", "Harness architecture", "Follow one user message through the Pi Agent, Host scheduling, Worker staging, review, terminology coordination, persistence, and completion.")}<div class="technical-intro terminology-entry"><span>New to Agent engineering?</span><p>Start with <a href="terminology.html">Agent terminology</a>. The manual defines Host, Harness, Runtime, staging, canonical, assignment, debt, and other terms before using them here.</p></div>
          <h2 id="architecture">Overall structure</h2><div class="architecture-map"><div class="architecture-node ui"><span>Interface</span><strong>Workbench / line review / LAN</strong><small>Collect current choices and render canonical sessions and artifacts</small></div><b>→</b><div class="architecture-node pi"><span>Pi Runtime</span><strong>Parent Agent</strong><small>Reason, call tools, and consume Steer and Follow-up</small></div><b>→</b><div class="architecture-node host"><span>YN Host</span><strong>Typed DomainRun</strong><small>Manifest, authority, queues, evidence, commit, and completion</small></div><b>⇄</b><div class="architecture-node workers"><span>Pi Children</span><strong>Translate / review / proofread / reuse</strong><small>Each sees only assignment-specific tools and context</small></div></div><p>Parent and Children share the Pi session runtime and append-only JSONL. The Host does not invent translation prose; it owns task identity, document scope, hashes, debt, and accepted validation evidence.</p>
          <h2 id="agent-loop">How one Agent turn advances</h2><div class="code-flow"><code>User AgentMessage</code><b>→</b><code>Agent.prompt()</code><b>→</b><code>toolCall</code><b>→</b><code>Host execute</code><b>→</b><code>toolResult</code><b>→</b><code>Agent.continue()</code></div><p>A tool failure returns a precise result to the same turn so the Agent can correct the call. Successful Host-terminal Child tools end the tool batch instead of spending another model call restating counts.</p><div class="contract-grid"><div class="contract-cell"><span>Steer</span><p>Consumed soon after the current tool returns; accepted only after entering the Child Pi session.</p></div><div class="contract-cell"><span>Follow-up</span><p>Consumed after current work, while the original message remains visible immediately.</p></div><div class="contract-cell"><span>Child completion</span><p>Writes lightweight state and wakes the Parent for a visible report.</p></div></div>
          <h2 id="typed-state">Core Host-owned state</h2><div class="table-wrap"><table><thead><tr><th>State</th><th>Contains</th><th>Problem solved</th></tr></thead><tbody><tr><td>Workflow identity</td><td>Kind, owner session, active or parked</td><td>Ordinary chat cannot acquire full-workflow authority</td></tr><tr><td>Document manifest</td><td>Identity, source/candidate paths, rows, order stages</td><td>Folder results cannot settle against the wrong file</td></tr><tr><td>Assignment</td><td>Document, ranges or exact rows, input hash, Worker, attempts</td><td>Reading context does not expand writes</td></tr><tr><td>Review evidence</td><td>Staging hash, risks, stable samples, verdicts, repair debt</td><td>Non-empty output cannot pretend to be accepted</td></tr><tr><td>Proofread evidence</td><td>Prescan hash, coverage, sample pool, Findings revision</td><td>Input changes invalidate only stale conclusions</td></tr><tr><td>Scheduler</td><td>Workers, tasks, active batches, gates, failures</td><td>Concurrency ceiling remains separate from workload</td></tr></tbody></table></div>
          <h2 id="tool-projection">How the toolset narrows</h2><p>The Host builds tools from the typed operation scope. Full translation, full proofreading, local repair, and read-only investigation receive different write boundaries; Children cannot spawn another subagent layer.</p><div class="scope-matrix"><div class="scope-row head"><span>Role</span><span>Main reads</span><span>May change</span><span>Host checks</span></div><div class="scope-row"><strong>Parent</strong><span>Project and Host state</span><span>Scheduling, assets, exact local writes</span><span>Session / document / scope</span></div><div class="scope-row"><strong>Translation Worker</strong><span>Owned rows and short context</span><span>Own staging</span><span>Row identity / protected payload / hash</span></div><div class="scope-row"><strong>Review Worker</strong><span>Selected risks and samples</span><span>Failure verdicts</span><span>Exact active review page</span></div><div class="scope-row"><strong>Proofread Worker</strong><span>Owned rows, signals, approved references</span><span>Findings</span><span>Scope / schema / no-op / evidence</span></div></div>
          <h2 id="scheduler">Dynamic queue and two Worker pools</h2><div class="scheduler-diagram"><div class="scheduler-source"><strong>File stages</strong><span>{ A, B } → C → { D, E }</span><small>Strict barriers between stages</small></div><b>→</b><div class="scheduler-queue"><strong>Shared assignment queue</strong><span>taskCount = actual debt chunks</span><small>May exceed Worker count</small></div><b>→</b><div class="scheduler-pools"><div><strong>Translation pool</strong><span>Write staging / exact repair</span></div><div><strong>Review pool</strong><span>Read risks and stable samples</span></div></div></div><p>A Worker atomically claims a real assignment before its runtime is created or reset. A failed task remains with its session for bounded recovery rather than moving to the back of the queue.</p>
          <h2 id="terminology">Terminology candidates and the conflict gate</h2>${flow(["Worker reports evidence", "Mechanical and semantic review pass", "Host records observation", "Merge or open conflict", "Parent decides", "Priority repair", "Resume queue"])}<ol class="technical-steps"><li><span>01</span><div><strong>Discovery is separate from acceptance</strong><p>A translation Worker reports names and evidence through validation; it cannot edit shared terminology directly.</p></div></li><li><span>02</span><div><strong>Observation follows acceptance</strong><p>The Host records the discovery only after the assignment passes mechanical validation and read-only review.</p></div></li><li><span>03</span><div><strong>Approved glossary wins</strong><p>Matching targets merge evidence; an approved target remains authoritative.</p></div></li><li><span>04</span><div><strong>Conflict closes new claims</strong><p>Running work reaches a safe gate while new assignment claims wait.</p></div></li><li><span>05</span><div><strong>A decision becomes exact repair</strong><p>The Host rescans the authoritative manifest and routes all affected rows to the active owner.</p></div></li><li><span>06</span><div><strong>One transaction boundary</strong><p>Candidate file, DomainRun terminology state, and persisted Host state commit or roll back together.</p></div></li></ol><div class="note"><strong>When candidate collection is off</strong>Existing candidates remain read-only references, while no new candidate, conflict gate, or candidate-derived debt is created.</div>
          <h2 id="review-loop">Translation review and failure takeover</h2><div class="formula"><code>write staging</code><b>→</b><code>mechanical scan</code><b>→</b><code>read-only review</code><b>→</b><code>exact repair</code><b>→</b><code>atomic promote</code></div><p>Review covers every high-risk row and a stable square-root sample of ordinary rows. Target-language punctuation alone does not create a repair loop. A repeated rejected hash means no progress and fails immediately.</p><p>If bounded Child repair is exhausted but staging is still valid, the Host promotes the hash-current range to Parent ownership and returns only exact failed rows. Provider exhaustion or an unverifiable staging handoff creates an explicit recovery boundary.</p>
          <h2 id="warning-postcheck">Final warning postcheck</h2><p>After blocking findings reach zero, warnings already accepted by the same chunk review evidence are not reopened. The rest are paged to the Parent as canonical paired rows.</p><div class="code-flow"><code>inspectTranslationWarnings</code><b>→</b><code>paired source + translation windows</code><b>→</b><code>recordTranslationWarningChecks</code><b>→</b><code>false-positive evidence / exact repair</code></div>
          <h2 id="persistence">Persistence and recovery</h2><div class="table-wrap"><table><thead><tr><th>Store</th><th>Contents</th><th>Trusted when</th></tr></thead><tbody><tr><td>Parent Pi JSONL</td><td>Messages, tool calls/results, compaction, Host custom entries</td><td>Session and project owner match</td></tr><tr><td>Child Pi JSONL</td><td>Complete assignment conversation and retries</td><td>Parent ownership and Child session reference match</td></tr><tr><td>Host state</td><td>Manifest, assignments, debt, coverage, batches, recovery boundaries</td><td>Document and input identity remain current</td></tr><tr><td>Translation staging</td><td>Hash-current candidate and pending review or repair</td><td>Path, rows, range input hash, and candidate hash match</td></tr><tr><td>Reuse audit store</td><td>Owner, source/candidate hashes, retained baseline, row verdicts</td><td>Same Parent session and batch remain current</td></tr></tbody></table></div><p>Staging promotion, canonical files, DomainRun revision, alignment evidence, and Host JSONL form a rollback-capable commit boundary.</p>
          <h2 id="token-efficiency">Why it saves tokens</h2><div class="formula"><span>One Child context</span><b>≈</b><code>system contract</code><b>+</b><code>owned rows</code><b>+</b><code>short boundary</code><b>+</b><code>matched assets</code><b>+</b><code>current debt</code></div><div class="three-col"><article class="topic-card"><span class="num">Host</span><h3>Mechanical work stays in code</h3><p>Manifests, hashes, protected payloads, samples, and coverage are not repeatedly reasoned about by models.</p></article><article class="topic-card"><span class="num">Index</span><h3>Inject only direct matches</h3><p>Full glossaries and character bibles do not enter every assignment.</p></article><article class="topic-card"><span class="num">Sparse</span><h3>Dispatch only real debt</h3><p>Reused rows, accepted ranges, and false-positive warnings do not re-enter translation.</p></article><article class="topic-card"><span class="num">Review</span><h3>Passing rows stay silent</h3><p>Reviewers report failures, not an explanation for every good row.</p></article><article class="topic-card"><span class="num">Session</span><h3>Persistent Workers, reset context</h3><p>The runtime is reused while active context resets between assignments.</p></article><article class="topic-card"><span class="num">State</span><h3>Large state remains in Host</h3><p>Manifests, transcripts, audits, and coverage arrays do not flood Parent context.</p></article></div>
          <h2 id="observability">Observability</h2><div class="table-wrap"><table><thead><tr><th>Object</th><th>Evidence</th><th>Question answered</th></tr></thead><tbody><tr><td>Provider</td><td>Session, provider, model, sanitized cause chain, WS attempts</td><td>Model, proxy, WS/SSE, or fetch failure?</td></tr><tr><td>Assignment</td><td>Document, scope, Worker, staging, attempt, review debt</td><td>Which chunk failed, and can it resume?</td></tr><tr><td>Terminology gate</td><td>Observed targets, conflict source, affected rows, priority queue</td><td>Why is the queue waiting, and what will be repaired?</td></tr><tr><td>UI</td><td>Structured thinking, tool, queue update, Child card</td><td>Reasoning, tool use, review, or waiting?</td></tr><tr><td>Completion</td><td>Coverage, accepted scopes, pending assets, validator debt</td><td>Why did the model reply before the workflow completed?</td></tr></tbody></table></div>`;
      },
      functions(h) {
        const groups = [...new Set([...h.data.parentFunctions, ...h.data.childFunctions].map((item) => item.group))].sort();
        return `${h.pageHead("Technical manual C", `Function Registry: ${h.data.metrics.callableSurfaces} callable surfaces`, `The Parent has ${h.data.metrics.parentFunctions} surfaces and Children have ${h.data.metrics.childFunctions}. Three read-only file tools exist on both sides with different authority, yielding ${h.data.metrics.uniqueFunctions} unique names.`)}<div class="technical-intro"><span>How to use this page</span><p>Filter by runtime or group, then expand one Function. Function names and model-authored parameters remain unchanged across languages.</p></div>
          <h2 id="scope">Runtime responsibilities</h2><div class="scope-matrix"><div class="scope-row head"><span>Runtime</span><span>Reads</span><span>May produce</span><span>Terminal action</span></div><div class="scope-row"><strong>Parent</strong><span>Current project, explicit external references, Host state</span><span>Scheduling, candidates, Findings, project assets</span><span>Consolidate through completion gate</span></div><div class="scope-row"><strong>Translation Child</strong><span>Owned rows, short context, matched assets</span><span>Own staging and discoveries</span><span>Validate owned scope</span></div><div class="scope-row"><strong>Review Child</strong><span>Risk rows, samples, short neighborhood</span><span>Failed verdicts only</span><span>Submit review</span></div><div class="scope-row"><strong>Proofread Child</strong><span>Owned rows, signals, approved references</span><span>Findings and evidence-backed candidates</span><span>Write Findings</span></div><div class="scope-row"><strong>Reuse Child</strong><span>Selected source/translation pairs</span><span>reuse / retranslate verdicts</span><span>Submit audit</span></div></div>
          <h2 id="registry">Complete Registry</h2><div class="filters"><input id="function-search" type="search" placeholder="Search Function, asset, scope, or result"><select id="runtime-filter"><option value="">Parent + Child</option><option value="parent">Parent Host</option><option value="child">Child runtime</option></select><select id="group-filter"><option value="">All groups</option>${groups.map((group) => `<option value="${h.esc(group)}">${h.esc(groupLabels[group] || group)}</option>`).join("")}</select></div><p id="function-count" class="image-caption"></p><div class="function-list" id="function-list">${functionCards(h.data, "parent", h)}${functionCards(h.data, "child", h)}</div>
          <h2 id="composition">Four common call chains</h2><div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Parent</th><th>Child</th></tr></thead><tbody><tr><td>Full translation</td><td><code>inspectTranslationContext</code> → <code>runTranslationSubagents</code> → warnings / final validation</td><td>read source → write staging → validate → independent review</td></tr><tr><td>Full proofreading</td><td>inspect → prescan → <code>runProofreadSubagents</code> → candidate decisions → finalize</td><td>read context → optional reference → write findings</td></tr><tr><td>Exact repair</td><td>write exact lines → inspect alignment → read paired rows → record failures → validate</td><td>read bound rows → repair Host-authorized lines only</td></tr><tr><td>Reuse audit</td><td>prepare → run audit → apply one decision</td><td>read selected pairs → submit binary verdicts</td></tr></tbody></table></div>`;
      }
    }
  };
})();
